package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class AssetRelationshipsAcceptance {
    static String api(String id){return "/api/openservice/assets/"+id+"/relationships";}
    static Map<String,Object> result(java.net.http.HttpResponse<byte[]> response)throws Exception{return TransferAcceptance.result(response,200);}
    static String asset(Store.Db db,String title)throws Exception{return Service.create(db,"cmdb_ci",map("short_description",title),"admin").get("sys_id").toString();}
    static Map<String,Object> change(String direction,String id,boolean remove){return map("direction",direction,"related_id",id,"remove",remove);}
    static void run(WorkflowSupport h)throws Exception{
        h.account("RelationReader","reader");String base,one,two,hidden,incoming;try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);base=asset(db,"Base <script>");one=asset(db,"Dependency one");two=asset(db,"Dependency two");hidden=asset(db,"Hidden Dependency");incoming=asset(db,"Incoming asset");RecordAccess.change(db,Service.record(db,"cmdb_ci",hidden),actor,map("visibility","private","owner_id",actor));db.connection.commit();}String path=api(base);assertEquals(0,result(h.get(path,auth("RelationReader"))).get("total"));
        for(String id:List.of(one,hidden,two))result(h.json("POST",path,change("dependencies",id,false),auth("admin")));result(h.json("POST",path+"/choose",change("dependents",incoming,false),auth("admin")));result(h.json("POST",path,change("dependencies",one,false),auth("admin")));var first=result(h.get(path+"?limit=1",auth("RelationReader")));assertEquals(2,first.get("total"));assertEquals(one,objects(first.get("items")).getFirst().get("value"));assertEquals(1,first.get("next_offset"));var second=result(h.get(path+"?limit=1&offset=1",auth("RelationReader")));assertEquals(two,objects(second.get("items")).getFirst().get("value"));assertEquals(-1,second.get("next_offset"));assertEquals(0,objects(result(h.get(path+"?offset=1000000",auth("RelationReader"))).get("items")).size());assertEquals(3,result(h.get(path,auth("admin"))).get("total"));assertEquals(incoming,objects(result(h.get(path+"?direction=dependents",auth("RelationReader"))).get("items")).getFirst().get("value"));
        var choice=result(h.get(path+"/choose?q=Dependency&limit=1",auth("admin")));assertEquals(3,choice.get("total"));assertEquals(1,objects(choice.get("items")).size());assertEquals(1,choice.get("next_offset"));assertEquals(1,objects(result(h.get(path+"/choose?q=Dependency&limit=1&offset=1",auth("admin"))).get("items")).size());new Store(h.environment);assertEquals(3,result(h.get(path,auth("admin"))).get("total"));
        result(h.json("POST",path,change("dependencies",one,true),auth("admin")));result(h.json("POST",path,change("dependencies",one,true),auth("admin")));assertEquals(1,result(h.get(path,auth("RelationReader"))).get("total"));var impact=result(h.get(PlatformOperationsAcceptance.ROOT+"dependencies/"+two,auth("RelationReader")));assertTrue(impact.toString().contains(base));result(h.json("POST",path,change("dependents",incoming,true),auth("admin")));assertEquals(0,result(h.get(path+"?direction=dependents",auth("RelationReader"))).get("total"));
        Map<String,Object> schema;try(var db=h.store.open()){schema=Service.schema(db,"cmdb_ci");var restricted=new LinkedHashMap<>(schema);restricted.put("field_rules",map("short_description",map("type","string","read_roles",List.of("admin"))));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='cmdb_ci'",JSON.writeValueAsString(restricted));db.connection.commit();}try{var page=result(h.get(path,auth("RelationReader")));assertEquals(two,objects(page.get("items")).getFirst().get("label"));assertFalse(object(page.get("source")).containsKey("short_description"));}finally{try(var db=h.store.open()){db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='cmdb_ci'",JSON.writeValueAsString(schema));db.connection.commit();}}
    }
    static void boundaries(WorkflowSupport h)throws Exception{
        h.account("RelationReader","reader");String base,other,wrong;try(var db=h.store.open()){PlatformFoundationTest.bind(db);base=asset(db,"Restricted relations");other=asset(db,"Other relation");wrong=Service.create(db,"incident",map("short_description","Wrong kind"),"admin").get("sys_id").toString();db.connection.commit();}String path=api(base),browser="/record/cmdb_ci/"+base+"/relationships";var input=change("dependencies",other,false);
        assertEquals(401,h.get(path,null).statusCode());assertEquals(403,h.get(path+"/choose",auth("RelationReader")).statusCode());assertEquals(403,h.json("POST",path,input,auth("RelationReader")).statusCode());assertEquals(405,h.json("PUT",path,input,auth("admin")).statusCode());for(String query:List.of("bad=x","direction=invalid","limit=0","limit=101","offset=-1","offset=1000001","direction=dependents&direction=dependencies"))assertEquals(400,h.get(path+"?"+query,auth("admin")).statusCode(),query);assertEquals(400,h.get(path+"/choose?bad=x",auth("admin")).statusCode());assertEquals(400,h.json("POST",path+"?direction=dependencies",input,auth("admin")).statusCode());
        for(var bad:List.of(map(),map("direction",3,"related_id",other,"remove",false),map("direction","invalid","related_id",other,"remove",false),map("direction","dependencies","related_id",other,"remove","false"),change("dependencies",base,false))){assertEquals(400,h.json("POST",path,bad,auth("admin")).statusCode());}var nil=change("dependencies",other,false);nil.put("direction",null);assertEquals(400,h.json("POST",path,nil,auth("admin")).statusCode());for(String id:List.of(id(),wrong))assertEquals(404,h.json("POST",path,change("dependencies",id,false),auth("admin")).statusCode());assertEquals(404,h.get(api(id()),auth("admin")).statusCode());assertEquals(404,h.get(api(wrong),auth("admin")).statusCode());assertEquals(403,h.form(browser,input,auth("admin")).statusCode());assertEquals(400,h.protectedForm(browser,map("direction","dependencies","related_id",other),auth("admin")).statusCode());assertEquals(302,h.protectedForm(browser,input,auth("admin")).statusCode());
        Map<String,Object> schema;try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);RecordAccess.change(db,Service.record(db,"cmdb_ci",base),actor,map("visibility","private","owner_id",actor));schema=Service.schema(db,"cmdb_ci");db.connection.commit();}assertEquals(404,h.get(path,auth("RelationReader")).statusCode());try{try(var db=h.store.open()){var denied=new LinkedHashMap<>(schema);denied.put("record_roles",map("read",List.of("agent")));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='cmdb_ci'",JSON.writeValueAsString(denied));db.connection.commit();}assertEquals(403,h.get(path,auth("admin")).statusCode());assertEquals(403,h.json("POST",path,input,auth("admin")).statusCode());}finally{try(var db=h.store.open()){db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='cmdb_ci'",JSON.writeValueAsString(schema));db.connection.commit();}}
    }
}
